213	  /**
214	   * Start listening for edits via RPC.
215	   */
216	  public void start() throws IOException {
217	    Preconditions.checkState(!isStarted(), "JN already running");
218	
219	    try {
220	
221	      for (File journalDir : localDir) {
222	        validateAndCreateJournalDir(journalDir);
223	      }
224	      DefaultMetricsSystem.initialize("JournalNode");
225	      JvmMetrics.create("JournalNode",
226	          conf.get(DFSConfigKeys.DFS_METRICS_SESSION_ID_KEY),
227	          DefaultMetricsSystem.instance());
228	
229	      InetSocketAddress socAddr = JournalNodeRpcServer.getAddress(conf);
230	      SecurityUtil.login(conf, DFSConfigKeys.DFS_JOURNALNODE_KEYTAB_FILE_KEY,
231	          DFSConfigKeys.DFS_JOURNALNODE_KERBEROS_PRINCIPAL_KEY,
232	          socAddr.getHostName());
233	
234	      registerJNMXBean();
235	
236	      httpServer = new JournalNodeHttpServer(conf, this,
237	          getHttpServerBindAddress(conf));
238	      httpServer.start();
239	
240	      httpServerURI = httpServer.getServerURI().toString();
241	
242	      rpcServer = new JournalNodeRpcServer(conf, this);
243	      rpcServer.start();
244	    } catch (IOException ioe) {
245	      //Shutdown JournalNode of JournalNodeRpcServer fails to start
246	      LOG.error("Failed to start JournalNode.", ioe);
247	      this.stop(1);
248	      throw ioe;
249	    }
250	  }
