323	  /**
324	   * Return the directory inside our configured storage
325	   * dir which corresponds to a given journal. 
326	   * @param jid the journal identifier
327	   * @return the file, which may or may not exist yet
328	   */
329	  private File getLogDir(String jid, String nameServiceId) throws IOException{
330	    String dir = null;
331	    if (nameServiceId != null) {
332	      dir = conf.get(DFSConfigKeys.DFS_JOURNALNODE_EDITS_DIR_KEY + "." +
333	          nameServiceId);
334	    }
335	    if (dir == null) {
336	      dir = conf.get(DFSConfigKeys.DFS_JOURNALNODE_EDITS_DIR_KEY,
337	          DFSConfigKeys.DFS_JOURNALNODE_EDITS_DIR_DEFAULT);
338	    }
339	
340	    File journalDir = new File(dir.trim());
341	    if (!localDir.contains(journalDir)) {
342	      //It is a federated setup, we need to validate journalDir
343	      validateAndCreateJournalDir(journalDir);
344	      localDir.add(journalDir);
345	    }
346	
347	    Preconditions.checkArgument(jid != null &&
348	        !jid.isEmpty(),
349	        "bad journal identifier: %s", jid);
350	    assert jid != null;
351	    return new File(journalDir, jid);
352	  }
